const CATEGORY_KEYS = ["arcade", "shooter", "puzzle", "platformer", "racing", "sports", "board", "casual", "3d", "word-quiz", "projects"];
let activeCategory = "all";
let searchQuery = "";
let selectedId = "";

function esc(value: string): string {
  return value.replace(/[&<>"']/g, char => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;"
  })[char] || char);
}

function copy(lang: CatalogLanguage, key: string): string {
  return COPY[lang]?.[key] || COPY.EN[key] || key;
}

function filteredEntries(): CatalogEntry[] {
  const query = searchQuery.trim().toLocaleLowerCase();
  return ENTRIES.filter(entry => {
    const categoryMatches = activeCategory === "all" || entry.category === activeCategory;
    const haystack = [entry.name, entry.category, entry.tech, entry.description, entry.tags].join(" ").toLocaleLowerCase();
    return categoryMatches && (!query || haystack.includes(query));
  });
}

function renderCards(lang: CatalogLanguage): string {
  const filtered = filteredEntries();
  const cards = filtered.map(entry => `
    <article class="open-game-card" data-open-game-card>
      <div class="open-game-card-top"><span class="open-game-category">${esc(copy(lang, entry.category)) === entry.category ? esc(entry.category) : esc(copy(lang, entry.category))}</span><span class="open-game-tech">${esc(entry.tech)}</span></div>
      <h3>${esc(entry.name)}</h3>
      <p>${esc(entry.description)}</p>
      <small>${esc(entry.tags)}</small>
      <div class="open-game-actions">
        <button type="button" class="open-game-primary" data-open-game-play="${esc(entry.id)}">${entry.kind === "game" ? esc(copy(lang, "play")) : esc(copy(lang, "open"))}</button>
        <button type="button" class="open-game-secondary" data-open-game-source="${esc(entry.id)}">${esc(copy(lang, "source"))}</button>
      </div>
    </article>`).join("");
  const count = document.querySelector<HTMLElement>("[data-open-game-count]");
  if (count) count.textContent = String(filtered.length);
  return cards || `<p class="open-game-empty">${esc(copy(lang, "empty"))}</p>`;
}

export function renderOpenGamesCatalog(language: CatalogLanguage): string {
  const t = (key: string) => esc(copy(language, key));
  if (selectedId) {
    const entry = ENTRIES.find(item => item.id === selectedId);
    if (!entry) selectedId = "";
    else if (entry.kind === "resource") {
      return `
        <div class="content portal-layout game-portal open-games-portal" data-portal-layout="game">
          <div class="section-head portal-block game-section-head"><div><h2>GAME</h2><p>${esc(entry.name)}</p></div><button class="open-game-back" data-open-game-back type="button">${t("back")}</button></div>
          <section class="open-game-resource-detail">
            <span class="open-game-category">${t("projects")}</span><h3>${esc(entry.name)}</h3><p>${esc(entry.description)}</p><p><strong>${t("tech")}:</strong> ${esc(entry.tech)}</p><p>${t("license")}</p>
            <div class="open-game-actions"><button class="open-game-primary" type="button" data-open-game-url="${esc(entry.url)}">${t("open")}</button><button class="open-game-secondary" type="button" data-open-game-url="${esc(entry.source)}">${t("source")}</button></div>
          </section>
        </div>`;
    } else {
      return `
        <div class="content portal-layout game-portal open-games-portal" data-portal-layout="game">
          <div class="section-head portal-block game-section-head"><div><h2>GAME</h2><p>${esc(entry.name)}</p></div><button class="open-game-back" data-open-game-back type="button">${t("back")}</button></div>
          <section class="open-game-player">
            <div class="open-game-player-tools"><span>${esc(entry.name)}</span><button type="button" class="open-game-secondary" data-open-game-url="${esc(entry.url)}">${t("external")}</button></div>
            <iframe class="open-game-frame" src="${esc(entry.url)}" title="${esc(entry.name)}" allow="autoplay; fullscreen; gamepad; clipboard-read; clipboard-write" allowfullscreen loading="eager" referrerpolicy="strict-origin-when-cross-origin"></iframe>
          </section>
          <p class="open-game-disclaimer">${t("disclaimer")}</p>
        </div>`;
    }
  }
  return `
    <div class="content portal-layout game-portal open-games-portal" data-portal-layout="game">
      <div class="section-head portal-block game-section-head"><div><h2>GAME</h2><p>${t("subtitle")}</p></div></div>
      <section class="open-game-catalog">
        <div class="open-game-tools"><input type="search" data-open-game-search maxlength="80" value="${esc(searchQuery)}" placeholder="${t("search")}" aria-label="${t("search")}"><span class="open-game-count"><b data-open-game-count>${filteredEntries().length}</b> ${t("count")}</span></div>
        <div class="open-game-categories" role="group" aria-label="Game categories">
          <button type="button" data-open-game-category="all" class="${activeCategory === "all" ? "active" : ""}">${t("all")}</button>
          ${CATEGORY_KEYS.map(key => `<button type="button" data-open-game-category="${key}" class="${activeCategory === key ? "active" : ""}">${t(key)}</button>`).join("")}
        </div>
        <p class="open-game-disclaimer">${t("disclaimer")}</p>
        <div class="open-games-grid" data-open-games-grid>${renderCards(language)}</div>
      </section>
    </div>`;
}

export function bindOpenGamesCatalog(language: CatalogLanguage, rerender: () => void): void {
  document.querySelectorAll<HTMLButtonElement>("[data-open-game-category]").forEach(button => {
    button.addEventListener("click", () => {
      activeCategory = button.dataset.openGameCategory || "all";
      rerender();
    });
  });
  const grid = document.querySelector<HTMLElement>("[data-open-games-grid]");
  // Delegate card actions so Play/Source keep working after live search replaces the cards.
  grid?.addEventListener("click", event => {
    const button = (event.target as HTMLElement).closest<HTMLButtonElement>("[data-open-game-play], [data-open-game-source]");
    if (!button) return;
    if (button.dataset.openGamePlay) {
      selectedId = button.dataset.openGamePlay;
      rerender();
      return;
    }
    const entry = ENTRIES.find(item => item.id === button.dataset.openGameSource);
    if (entry) openExternalUrl(entry.source);
  });
  const search = document.querySelector<HTMLInputElement>("[data-open-game-search]");
  search?.addEventListener("input", () => {
    searchQuery = search.value;
    const grid = document.querySelector<HTMLElement>("[data-open-games-grid]");
    if (grid) grid.innerHTML = renderCards(language);
  });
  document.querySelectorAll<HTMLButtonElement>("[data-open-game-back]").forEach(button => {
    button.addEventListener("click", () => {
      stopOpenGamesSession();
      rerender();
    });
  });
  document.querySelectorAll<HTMLButtonElement>("[data-open-game-url]").forEach(button => {
    button.addEventListener("click", () => {
      const url = button.dataset.openGameUrl;
      if (url) openExternalUrl(url);
    });
  });
}

/** Unload active web games and return the GAME module to its catalog state. */
export function stopOpenGamesSession(): void {
  document.querySelectorAll<HTMLIFrameElement>(".open-game-frame").forEach(frame => {
    try { frame.src = "about:blank"; } catch {}
    frame.remove();
  });
  selectedId = "";
}
